before:
[package]
name = "manifold-app"
version = "0.1.0"
edition = "2024"
publish = false
default-run = "manifold"

[[bin]]
name = "manifold"
path = "src/main.rs"

[[bin]]
name = "generate-preset-thumbnails"
path = "src/bin/generate_preset_thumbnails.rs"
[[bin]]
name = "graph-tool"
path = "src/bin/graph_tool.rs"
[[bin]]
name = "render-import"
path = "src/bin/render_import.rs"

[dependencies]
bytemuck = { version = "1", features = ["derive", "min_const_generics"] }
inventory = "0.3"
manifold-compositor = { path = "../manifold-compositor" }
manifold-nodes-scene = { path = "../manifold-nodes-scene" }
manifold-nodes-image = { path = "../manifold-nodes-image" }
manifold-node-engine = { path = "../manifold-node-engine" }
manifold-core = { path = "../manifold-core" }
manifold-editing = { path = "../manifold-editing" }
manifold-ui = { path = "../manifold-ui" }
manifold-ui-paint = { path = "../manifold-ui-paint" }
manifold-playback = { path = "../manifold-playback" }
manifold-renderer = { path = "../manifold-renderer" }
manifold-io = { path = "../manifold-io" }
manifold-media = { path = "../manifold-media" }
manifold-gpu = { path = "../manifold-gpu" }
manifold-led = { path = "../manifold-led" }
manifold-audio = { path = "../manifold-audio" }
# `gpu` feature: the app renders the spectrogram waterfall, so it needs the GPU
# renderer (the worker, via manifold-audio, uses the CPU CQT only).
manifold-spectral = { path = "../manifold-spectral", features = ["gpu"] }
manifold-recording = { path = "../manifold-recording" }
sha2 = "0.10"
winit = { workspace = true }
log = { workspace = true }
env_logger = { workspace = true }
rfd = "0.15"
serde = { workspace = true }
serde_json = { workspace = true }
crossbeam-channel = "0.5"
ahash = { workspace = true }
# `UIRoot::closed_overlays` (OVERLAY_SESSIONS_AND_PICKER_DESIGN.md section 3) — a
# handful of overlay ids per frame at most, so a small inline buffer avoids a
# heap alloc on the common empty/one-close case. Already resolved in
# Cargo.lock via a transitive dep.
smallvec = "1"
mimalloc = "0.1"
libc = "0.2"
parking_lot = { workspace = true }
arboard = "3"
# Graph output dump (visual inspection): 16-bit PNG encode + f16 decode.
png = "0.18"
half = "2"
manifold-profiler = { path = "../manifold-profiler", optional = true }
# Headless UI snapshot harness (feature `ui-snapshot`): PNG encode of the
# rendered tree. Optional so it never enters the shipping binary.
image = { version = "0.25", default-features = false, features = ["png"] }
muda = "0.19.3"

# macOS platform dependencies
[target.'cfg(target_os = "macos")'.dependencies]
io-surface = "0.16"
core-foundation = "0.10"
raw-window-handle = "0.6"
objc2 = "0.6"
# "objc2-core-foundation": pulls in NSPoint/NSRect (CGPoint/CGRect aliases),
# needed by drag_interpose.rs to convert draggingLocation into cursor_pos's
# logical top-left convention. Already in Cargo.lock (transitive via winit).
objc2-foundation = { version = "0.3", features = ["NSString", "NSNotification", "NSURL", "NSArray", "objc2-core-foundation"] }
# P3 (docs/TIMELINE_INGEST_DESIGN.md section 4): general-pasteboard access for the
# Finder-paste arbitration. macos_pasteboard.rs is the sole module allowed
# to name these types.
objc2-app-kit = { version = "0.3", features = [
    "NSPasteboard",
    "NSPasteboardItem",
] }

[features]
whitewater-oracle = ["manifold-renderer/whitewater-oracle", "gpu-proofs"]
water-race-probes = ["manifold-renderer/water-race-probes", "gpu-proofs"]
matter-perf-proofs = ["manifold-renderer/matter-perf-proofs", "gpu-proofs"]
fluid-perf-proofs = ["manifold-renderer/fluid-perf-proofs", "gpu-proofs"]
rt-perf-proofs = ["manifold-renderer/rt-perf-proofs", "gpu-proofs"]
gpu-proofs = ["manifold-editing/gpu-proofs", "manifold-compositor/gpu-proofs", "manifold-nodes-scene/gpu-proofs", "manifold-nodes-image/gpu-proofs", "manifold-renderer/gpu-proofs", "manifold-node-engine/gpu-proofs"]
ui-automation = []
profiling = ["dep:manifold-profiler"]
ui-snapshot = []
# P3 release-journey harness (docs/OFFLINE_AUDIO_REACTIVE_EXPORT_DESIGN.md):
# headless end-to-end export proofs (audio-reactive + LFO + round-trip),
# plus the deliberate corridor reference-project acceptance journey.
# Deliberate-run only, like gpu-proofs — GPU + video encode, minutes-long.
# `dep:image` for PNG luma decode, same optional dep `ui-snapshot` uses.
journey-proofs = []
# `cargo xtask perf-soak` (docs/PERF_BUDGET_GATE_DESIGN.md P1): headless
# frame-budget soak of a real project. Needs `profiling` for
# `manifold-profiler`'s per-frame section-timing collector (min/p50/p95/max +
# worst-frame breakdown come from its FrameRecord/SessionSummary, not a new
# timing framework).
perf-soak = ["profiling"]

[dev-dependencies]
manifold-foundation = { path = "../manifold-foundation" }
manifold-physics = { path = "../manifold-physics" }
manifold-fluids = { path = "../manifold-fluids" }
glam = "0.29.3"
manifold-renderer = { path = "../manifold-renderer", features = ["testkit"] }
manifold-compositor = { path = "../manifold-compositor", features = ["testkit"] }
manifold-node-engine = { path = "../manifold-node-engine", features = ["testkit"] }
manifold-nodes-image = { path = "../manifold-nodes-image", features = ["testkit"] }
manifold-nodes-scene = { path = "../manifold-nodes-scene", features = ["testkit"] }
sha2 = "0.10"

[lints]
workspace = true

[[test]]
name = "renderer_contracts"
path = "tests/renderer_contracts.rs"

[[test]]
name = "renderer_gpu_proofs"
path = "tests/renderer_contracts/gpu_proofs/main.rs"
required-features = ["gpu-proofs"]

